CREATE TABLE "application" (
	"available_weekdays" text[] NOT NULL,
	"bolk" text NOT NULL,
	"created_at" timestamp with time zone NOT NULL,
	"double_position" boolean NOT NULL,
	"field_of_study_id" integer NOT NULL,
	"gender" text,
	"heard_about_us" text[] NOT NULL,
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "application_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"period_id" integer NOT NULL,
	"person_id" integer NOT NULL,
	"special_needs" text,
	"special_needs_consented_at" timestamp with time zone,
	"special_needs_consent_version" integer,
	"state" text NOT NULL,
	"team_interest" integer[] NOT NULL,
	"year_of_study" integer NOT NULL,
	CONSTRAINT "application_person_period_unique" UNIQUE("person_id","period_id"),
	CONSTRAINT "application_state" CHECK ("state" in ('Submitted', 'Withdrawn')),
	CONSTRAINT "application_bolk" CHECK ("bolk" in ('Bolk1', 'Bolk2', 'Both')),
	CONSTRAINT "application_gender" CHECK ("gender" is null or "gender" in ('Female', 'Male', 'Other')),
	CONSTRAINT "application_year_of_study" CHECK ("year_of_study" between 1 and 5),
	CONSTRAINT "application_weekdays" CHECK (cardinality("available_weekdays") > 0 and "available_weekdays" <@ array['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday']::text[]),
	CONSTRAINT "application_heard_about" CHECK ("heard_about_us" <@ array['Blesting', 'Stand', 'Web', 'Acquaintances', 'Board', 'Posters', 'StudentUnion']::text[]),
	CONSTRAINT "application_special_needs" CHECK (("special_needs" is null and "special_needs_consent_version" is null and "special_needs_consented_at" is null) or ("special_needs" is not null and length("special_needs") between 1 and 1000 and "special_needs_consent_version" is not null and "special_needs_consented_at" is not null))
);
